#!/usr/bin/env python3
"""Seed ~20 evergreen sea / underwater-life topics for the ocean channel.

Same contract as seed_history_topics.py: every topic carries real source
text so the LLM research stage has substance to work with. This runs in the
FIRST ytauto-cycle-sea build (before the state artifact exists).

Run: .venv/bin/python tools/seed_ocean_topics.py
"""
import subprocess
import sys

TOPICS = [
    ("Challenger Deep: the deepest place on Earth, reached three times", "https://en.wikipedia.org/wiki/Challenger_Deep",
     "Challenger Deep, at the southern end of the Mariana Trench in the western Pacific, sits about 10,935 metres below sea level — deeper than Mount Everest is tall. Jacques Piccard and Don Walsh reached it in 1960 aboard the bathyscaphe Trieste, spending 20 minutes on the bottom and reporting seeing a flatfish, a claim biologists still debate. James Cameron made a solo dive in 2012, and explorer Victor Vescovo reported reaching it in 2019 — finding, ominously, a plastic bag and candy wrappers at full ocean depth. Only a handful of humans have ever stood (sat) there."),
    ("The Bloop: the loudest underwater sound ever recorded, and what it really was", "https://en.wikipedia.org/wiki/The_Bloop",
     "In 1997 NOAA hydrophones across the Pacific picked up a sound louder than any known animal could make, tracked to a point in the remote South Pacific near Antarctica. It repeated, and analysts said no known creature had the body to move that much water. The internet decided it was a sea monster; NOAA later attributed it to an icequake — a massive iceberg cracking off Antarctica. The saga made the SOFAR channel (a natural ocean sound highway at 1,000m depth) famous, and shows how the deep ocean can still sound like the unknown."),
    ("USS Nautilus: the first ship to travel under the North Pole", "https://en.wikipedia.org/wiki/USS_Nautilus_(SSN-571)",
     "On 3 August 1958 the USS Nautilus, the world's first nuclear-powered submarine, became the first vessel to cross beneath the North Pole — sailing under the ice cap from the Pacific to the Atlantic in about four days without surfacing once. Earlier diesel-electric boats could not have made the trip: they had to surface to run engines and recharge. Nautilus had earlier (1955) proven nuclear propulsion at sea, and its 1958 polar transit proved the US Navy could hide a strategic deterrent anywhere under the Arctic ice."),
    ("Thistlegorm: the Red Sea wreck that is a war museum on the seabed", "https://en.wikipedia.org/wiki/SS_Thistlegorm",
     "The SS Thistlegorm, a British armed merchant ship, was bombed by German aircraft in October 1941 while anchored near Egypt's Ras Muhammad and sank with an extraordinary cargo: Norton motorcycles, Bren guns, Lee-Enfield rifles, a stack of Royal Navy boots, Bedford trucks and even two LMS steam locomotives bound for Egypt. Today at 30m depth it is one of the planet's most famous wreck dives, its holds still crammed with 1941's cargo and its decks growing soft corals — a time capsule of the war at the bottom of the Red Sea."),
    ("The blue whale: the largest animal that has ever lived", "https://en.wikipedia.org/wiki/Blue_whale",
     "The blue whale reaches 30 metres and 150-190 tonnes — bigger than any dinosaur known — yet it eats one of the smallest animals: swarms of krill, up to 4 tonnes a day, filtered through baleen plates. Its heart is roughly the size of a small car and beats as slowly as twice per minute during deep dives. Blue-whale songs carry across entire ocean basins. Industrial whaling killed perhaps 360,000 of them; the 1966 international ban let the species slowly recover, and it remains an endangered success story in progress."),
    ("Whale fall: how a dead whale builds a city that lasts 50 years", "https://en.wikipedia.org/wiki/Whale_fall",
     "When a whale dies and sinks, its carcass becomes an ecosystem. Stage one feeds sharks, hagfish and crustaceans; stage two (months to years) is run by bone-eating worms (Osedax) that drill into the blubber with acid; stage three lasts decades as bacteria break down lipids in the bones and release sulphides, supporting clams and mussels the way hydrothermal vents do. Over 100 species have been found only on whale falls, some new to science — and many of them are thought to have used falls as stepping-stone habitats between deep-sea vents."),
    ("Giant kelp: a forest that grows 60 centimetres a day", "https://en.wikipedia.org/wiki/Giant_kelp",
     "Macrocystis pyrifera, giant kelp, is the fastest-growing organism on Earth — up to 60 centimetres per day, reaching 45 metres from the seabed to the surface in a single season. Each plant anchors with a holdfast and floats its blades on gas-filled pneumatocysts. The forests off California and Chile shelter sea otters, garibaldi, rockfish and entire food webs; the otters' return after the fur-trade era famously rebuilt the kelp by eating the sea urchins that had grazed it flat — one of ecology's textbook trophic cascades."),
    ("Coral bleaching: when the ocean's cities turn white", "https://en.wikipedia.org/wiki/Coral_bleaching",
     "Coral is an animal farming algae: the zooxanthellae inside its tissue photosynthesise and feed the reef. When water stays even 1-2C above the normal summer maximum, the stressed coral expels its algae — turning white ('bleaching'). It can recover, but a prolonged event kills it. Mass bleaching struck the Great Barrier Reef in 1998, 2002, 2016, 2017, 2020, 2022 and 2024, with the 2016-17 events killing about half its shallow corals. Reefs cover under 1% of the ocean floor but shelter a quarter of marine species."),
    ("Why most deep-sea creatures glow", "https://en.wikipedia.org/wiki/Bioluminescence",
     "Below about 1,000 metres there is no sunlight, yet up to three-quarters of the animals down there make their own — bioluminescence, a chemical reaction in luciferin and luciferase. Anglerfish dangle glowing lures; the vampire squid turns itself inside out and flashes blue photophores; dragonfish emit infrared to hunt without being seen; hatchetfish use belly lights as counter-illumination camouflage, erasing their silhouette from below. Even snowfall — the daily descent of dead glowing plankton — lights up the deep when it drifts past a camera."),
    ("Hydrothermal vents: life that never needed the sun", "https://en.wikipedia.org/wiki/Hydrothermal_vent",
     "In 1977 scientists in the submersible Alvin, exploring the Galapagos Rift at 2,500 metres, found swarms of giant clams and tube worms around hot springs nobody expected. The black smokers spout water at up to 400C loaded with sulphides; instead of photosynthesis, microbes there run chemosynthesis, oxidising hydrogen sulphide for energy. It rewrote biology's rules — life could be powered by chemistry alone — and made vent ecosystems the leading model for how life might begin on ocean worlds like Europa and Enceladus."),
    ("Lost City: the hydrothermal field that burns cold and alkaline", "https://en.wikipedia.org/wiki/Lost_City_hydrothermal_field",
     "Discovered in 2000 on the Atlantis Massif near the Mid-Atlantic Ridge, Lost City is nothing like a black smoker: its carbonate chimneys, some over 60 metres tall, vent alkaline water at 40-90C, driven by serpentinisation — seawater reacting with the mantle rock below. The chemistry mirrors reactions hypothesised for the origin of life, and the field has been active for at least 120,000 years. It is also a cautionary tale: it was nearly mined for 'rare earths' before protection efforts intervened."),
    ("Milky seas: when the whole ocean glows like milk", "https://en.wikipedia.org/wiki/Milky_sea",
     "Sailors have for centuries described 'milky seas' — stretches of ocean glowing uniformly white-blue for hundreds of kilometres, bright enough to read by. For decades science doubted them; then in 1995 a British frigate's crew confirmed one in the Arabian Sea, and in 2005 satellites photographed a 15,000-square-kilometre glow off Somalia. The light comes from bioluminescent bacteria (Vibrio harveyi and relatives) in their billions, churning in a chemical reaction that can last three nights. It remains one of the ocean's rarest spectacles."),
    ("The Sargasso Sea: the only sea with no shores", "https://en.wikipedia.org/wiki/Sargasso_Sea",
     "Bounded not by land but by four ocean currents — the North Atlantic Gyre — the Sargasso Sea is a slow, calm raft of floating Sargassum weed, some of it buoyant for millennia via gas bladders. Columbus's crews noted the floating plants in 1492. It is the spawning ground of both Atlantic eel species; the adults migrate from European and American rivers across the ocean to spawn and die here — and no one has ever seen a baby American eel in the wild. Young sea turtles and many fish use the weed as shelter."),
    ("Colossal squid: the biggest invertebrate on the planet", "https://en.wikipedia.org/wiki/Colossal_squid",
     "Mesonychoteuthis hamiltoni, the colossal squid, outweighs even the giant squid — up to 700kg and perhaps 15 metres with tentacles — and it is armed with rotating hooks on its clubbed tentacles and the largest eyes in the animal kingdom: 27cm across, tuned to spot sperm whales in the dark. It lives in the Antarctic deep and is known mostly from fragments in whale stomachs; a near-complete specimen was captured in 2007 and dissected in New Zealand in 2014, still holding surprises like the beak-to-body ratio."),
    ("Sac Actun: the Maya underworld, flooded and mapped", "https://en.wikipedia.org/wiki/Sistema_Sac_Actun",
     "Beneath Mexico's Yucatan peninsula, the jungle is riddled with flooded caves — the Sistema Sac Actun runs over 370 kilometres, the longest underwater cave system on Earth. To the ancient Maya these waters were Xibalba, entrances to the underworld, and divers have found pottery, offerings and human remains deep inside, along with the bones of Ice Age animals like giant sloths and mastodons. Divers map them line by line with tape and camera; each new connection can push the system's length into record territory."),
    ("Sea otters, urchins and the kelp: the comeback that saved a forest", "https://en.wikipedia.org/wiki/Sea_otter",
     "Sea otters were hunted to near-extinction for the fur trade — perhaps 100,000 killed by 1911, when international protection left only isolated colonies. They eat sea urchins, and urchins eat kelp. Where otters returned along the North Pacific coast, urchin barrens turned back into towering kelp forests within years, locking carbon and sheltering fish, seals and invertebrates — ecology's clearest trophic cascade in the wild. The recovery is fragile and uneven (great white shark predation and oil spills now limit it), but it is the ocean's best restoration story."),
    ("Titanic, found: 73 years later, 3,800 metres down", "https://en.wikipedia.org/wiki/RMS_Titanic_wreck",
     "The Titanic sank in April 1912 and stayed lost until 1 September 1985, when a joint American-French team using deep sonar found it at about 3,800 metres in the north Atlantic — 600km south of Newfoundland. The hull is split in two and is slowly being eaten by 'rusticles', iron-consuming bacteria that may dissolve the wreck entirely within decades. More than 5,500 artefacts have been recovered, and the site is now a protected memorial under UNESCO rules; ROVs and submersibles have filmed it repeatedly, including the famous bow railing."),
    ("Octopuses: three hearts, blue blood, and eight mini-brains", "https://en.wikipedia.org/wiki/Cephalopod",
     "An octopus has three hearts (two gill hearts, one systemic), copper-based blue blood, and a nervous system where two-thirds of its neurons sit in its arms — each arm can taste, decide and act semi-independently. They open jars, navigate mazes, recognise individual humans, and squirt water at light switches they dislike. The mimic octopus impersonates lionfish, flatfish and sea snakes; the blanket octopus carries stinging Portuguese man-o'-war tentacles as a weapon. Their intelligence evolved on a completely separate branch from ours — making them the closest thing to an alien mind on Earth."),
    ("Manta rays: gentle giants with the biggest brains in the sea", "https://en.wikipedia.org/wiki/Manta_ray",
     "Oceanic manta rays reach seven metres across and can weigh two tonnes, yet they are filter feeders drifting through plankton clouds with the largest brains of any fish — folded and enlarged in regions linked to learning and social behaviour. They visit cleaner stations on reefs, recognising the individual cleaner fish, and have been seen 'sunning' with fins spread at the surface. Manta rays are slow breeders — one pup every two to three years — which makes them extremely vulnerable to fishing pressure; all manta species are now internationally protected."),
    ("Whale song: the record that started the Save the Whales movement", "https://en.wikipedia.org/wiki/Songs_of_the_Humpback_Whale",
     "In 1970 Columbia Records released 'Songs of the Humpback Whale', recordings made by biologist Roger Payne and friends off Bermuda — humpbacks' eerie, rising, falling phrases carried over the ocean in structured 'songs' that can last 20 minutes and be repeated for hours. The album sold millions, became the most commercially successful nature record ever, and turned public opinion: within years it powered the anti-whaling movement that led to the 1986 moratorium. Humpback populations have since rebounded across most oceans, and their songs keep evolving, syllable by syllable, within each population."),
]

def main() -> int:
    ok = 0
    for title, url, summary in TOPICS:
        res = subprocess.run(
            [sys.executable, "-m", "ytauto", "discover", "--add", title,
             "--url", url, "--summary", summary],
            capture_output=True, text=True)
        line = (res.stdout or res.stderr).strip().splitlines()[-1] if (res.stdout or res.stderr) else ""
        print(("OK " if res.returncode == 0 else "XX "), line[:120])
        ok += res.returncode == 0
    print(f"\nseeded {ok}/{len(TOPICS)}")
    return 0 if ok == len(TOPICS) else 1

if __name__ == "__main__":
    sys.exit(main())
